// Controller independent public memory checks. No production content collection.
#![forbid(unsafe_code)]
use serde_json::{Value,json};
use water_node_manifest::v1 as u;
fn wire(raw:&str)->Value{serde_json::from_str(&u::to_json(&u::analyze_package_json(raw).unwrap()).unwrap()).unwrap()}
fn main(){let cases:Value=serde_json::from_str(include_str!("../../contracts/node-manifest-v1/cases.json")).unwrap();for c in cases["valid"].as_array().unwrap(){let e=u::analyze_package_json(c["raw"].as_str().unwrap()).unwrap();let v:Value=serde_json::from_str(&u::to_json(&e).unwrap()).unwrap();assert_eq!(v,c["expected"],"{}",c["id"]);assert_eq!(v,serde_json::to_value(e).unwrap());}for c in cases["errors"].as_array().unwrap(){assert_eq!(u::analyze_package_json(c["raw"].as_str().unwrap()).unwrap_err().to_string(),format!("{} at /manifest",c["error"].as_str().unwrap()));}let d32=format!("{{\"x\":{}{}}}","[".repeat(31),"]".repeat(31));assert!(u::analyze_package_json(&d32).is_ok());let d33=format!("{{\"x\":{}{}}}","[".repeat(32),"]".repeat(32));assert_eq!(u::analyze_package_json(&d33).unwrap_err().to_string(),"NestingTooDeep at /manifest");let max=format!("{{\"x\":\"{}\"}}","a".repeat(262136));assert_eq!(max.len(),262144);assert!(u::analyze_package_json(&max).is_ok());assert_eq!(u::analyze_package_json(&(max+" ")).unwrap_err().to_string(),"InputTooLarge at /manifest");for(field,limit)in [("scripts",128),("dependencies",4096),("devDependencies",4096),("peerDependencies",4096),("optionalDependencies",4096)]{let mut m=serde_json::Map::new();for n in 0..limit{m.insert(format!("dep-{n}"),json!("1"));}assert!(u::analyze_package_json(&json!({field:m}).to_string()).is_ok());m.insert("overflow".into(),json!("1"));assert_eq!(u::analyze_package_json(&json!({field:m}).to_string()).unwrap_err().to_string(),"TooManyEntries at /manifest");}assert_eq!(wire("{\"name\":\"CANARY_A\",\"scripts\":{\"a\":\"CANARY_SCRIPT\"}}"),wire("{\"scripts\":{\"b\":\"different\"},\"name\":\"CANARY_B\",\"ignored\":12}"));println!("{}",json!({"actual_U_public_API":true,"valid":11,"errors":19,"dynamic_limits":true,"filesystem_scanned":false}));}
